def esc(t): return html.escape(t, quote=True)

def ld(*objs):
    return '<script type="application/ld+json">' + json.dumps({'@context': 'https://schema.org', '@graph': list(objs)}, ensure_ascii=False) + '</script>'

def faq_ld(items, url):
    return {'@type': 'FAQPage', '@id': url + '#faq', 'mainEntity': [
        {'@type': 'Question', 'name': q, 'acceptedAnswer': {'@type': 'Answer', 'text': strip(a)}} for q, a in items]}

def strip(s):
    import re
    return re.sub(r'<[^>]+>', '', s)

def crumbs_ld(items):
    return {'@type': 'BreadcrumbList', 'itemListElement': [
        {'@type': 'ListItem', 'position': i + 1, 'name': n, 'item': BASE + '/' + u} for i, (u, n) in enumerate(items)]}

def faq_html(items):
    return '<div class="faq">' + ''.join(f'<details><summary>{esc(q)}</summary><div class="ans"><p>{a}</p></div></details>' for q, a in items) + '</div>'

