def practice_block(s):
    pref = {'yurist-po-dtp.html': ('ДТП', 'Дела по ДТП'), 'grazhdanskie-spory.html': ('Гражданские', 'Дела из практики')}.get(s['f'])
    items = [c for c in PRACTICE if pref and c['cat'].startswith(pref[0])]
    if not items: return ''
    return '<section class="sec sec--white"><div class="wrap"><div class="sec__head"><p class="over">Практика</p><h2>' + pref[1] + '</h2></div><div class="grid grid--2">' + ''.join(practice_card(c) for c in items) + '</div><p style="margin-top:24px"><a href="praktika.html">Вся практика →</a></p></div></section>'

